using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Net.NetworkInformation;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
namespace XHLLauncher {
 internal sealed class PhoneView : IDisposable {
  TcpListener listener; Thread thread; volatile bool active; readonly object gate=new object(); string json="{}";
  readonly string token; internal string Url {get;private set;}
  readonly Func<string, ActionResult> command;
  internal PhoneView(string key, Func<string, ActionResult> handler=null) {token=key;command=handler;}
  internal static IPAddress LocalAddress() {
   foreach(var n in NetworkInterface.GetAllNetworkInterfaces()) {if(n.OperationalStatus!=OperationalStatus.Up || n.NetworkInterfaceType==NetworkInterfaceType.Loopback)continue; var props=n.GetIPProperties(); if(props.GatewayAddresses.Count==0)continue; foreach(var a in props.UnicastAddresses) {var b=a.Address.GetAddressBytes();if(b.Length==4 && (b[0]==10 || (b[0]==192 && b[1]==168) || (b[0]==172 && b[1]>=16 && b[1]<=31)))return a.Address;}}
   throw new IOException("No private home-network IPv4 address found.");
  }
  internal void Start(IPAddress address,int port) {listener=new TcpListener(address,port);listener.Start(8);active=true;Url="http://"+address+":"+((IPEndPoint)listener.LocalEndpoint).Port+"/"+token+"/";thread=new Thread(Serve){IsBackground=true};thread.Start();}
  internal void Publish(object data){lock(gate)json=new JavaScriptSerializer().Serialize(data);}
  void Serve(){while(active)try{using(var c=listener.AcceptTcpClient()){c.ReceiveTimeout=2000;c.SendTimeout=2000;using(var stream=c.GetStream()){var bytes=new MemoryStream();int v;while(bytes.Length<8192 && (v=stream.ReadByte())>=0){bytes.WriteByte((byte)v);var a=bytes.GetBuffer();int n=(int)bytes.Length;if(n>=4 && a[n-4]==13 && a[n-3]==10 && a[n-2]==13 && a[n-1]==10)break;}
   string req=Encoding.ASCII.GetString(bytes.ToArray());string[] line=req.Split('\n')[0].Trim().Split(' ');string status="404 Not Found",type="text/plain",body="Not found";
   if(line.Length==3 && line[0]=="GET" && (line[1]=="/"+token+"/" || line[1]=="/"+token+"/status")) {status="200 OK";if(line[1].EndsWith("/status")){type="application/json";lock(gate)body=json;}else{type="text/html; charset=utf-8";body=Page;}}
   if(line.Length==3 && line[0]=="POST" && line[1].StartsWith("/"+token+"/command/")) {
    string op=line[1].Substring(("/"+token+"/command/").Length);
    bool authorized=false,originAllowed=true;
    foreach(string header in req.Split('\n')) {int colon=header.IndexOf(':');if(colon<0)continue;string name=header.Substring(0,colon).Trim(),value=header.Substring(colon+1).Trim();if(name.Equals("X-XHL-Key",StringComparison.OrdinalIgnoreCase))authorized=value==token;if(name.Equals("Origin",StringComparison.OrdinalIgnoreCase))originAllowed=value==new Uri(Url).GetLeftPart(UriPartial.Authority);}
    if(authorized && originAllowed && (op=="Start" || op=="Stop" || op=="Restart" || op=="Backup" || op=="AutoBackupOn" || op=="AutoBackupOff" || op=="RecoveryOn" || op=="RecoveryOff")) {var result=command==null?ActionResult.Fail("Controls are unavailable."):command(op);status=result.Success?"202 Accepted":"409 Conflict";type="application/json";body=new JavaScriptSerializer().Serialize(new {success=result.Success,message=result.Message});}
   }
   byte[] payload=Encoding.UTF8.GetBytes(body);byte[] headers=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+"\r\nContent-Type: "+type+"\r\nContent-Length: "+payload.Length+"\r\nCache-Control: no-store\r\nReferrer-Policy: no-referrer\r\nX-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY\r\nConnection: close\r\n\r\n");stream.Write(headers,0,headers.Length);stream.Write(payload,0,payload.Length);}}}catch{if(!active)return;}}
  public void Dispose(){active=false;if(listener!=null)listener.Stop();}
  const string Page=@"<!doctype html><html lang=""en""><head><meta charset=""utf-8""><meta name=""viewport"" content=""width=device-width,initial-scale=1""><meta name=""theme-color"" content=""#121416""><title>ShroudForge Launcher · Realm control</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{background:#121416;color:#e5dfd1;font:15px system-ui;margin:0}main{max-width:850px;margin:auto;padding:28px 18px 48px}header{display:flex;justify-content:space-between;align-items:center;margin:0 0 24px}h1{font:32px Georgia;margin:6px 0}h2{font-size:16px;margin:0 0 18px}small,.muted{color:#a5a8a5;font-size:12px;line-height:1.6}.eyebrow{color:#c2a66d;letter-spacing:.16em;font-size:10px;text-transform:uppercase}.sigil{color:#c2a66d;font:36px Georgia;border:1px solid #65573d;padding:8px 15px}.panel{background:#1c1f20;border:1px solid #353936;border-radius:12px;padding:20px;margin:14px 0}.hero{border-top:2px solid #a58b57}.state{font:24px Georgia;margin:8px 0}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#909590;margin-right:9px}.online .dot{background:#91b99c;box-shadow:0 0 12px #91b99c55}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.metric{background:#222627;border-radius:8px;padding:14px 12px}.metric strong{display:block;font-size:19px;font-weight:500;margin-top:8px}.actions{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}button{min-height:46px;border:1px solid #55584f;background:#292e2c;color:#e5dfd1;padding:11px 15px;border-radius:7px;font:inherit;cursor:pointer}button.primary{border-color:#a58b57;background:#393528}button.danger{border-color:#795953}button:disabled{opacity:.4;cursor:default}button:focus-visible{outline:2px solid #d6b777;outline-offset:3px}.row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid #333735}.row:last-child{border:0}.row strong{overflow-wrap:anywhere;min-width:0;display:block;font-weight:500;margin-bottom:4px}.switch{flex-shrink:0;min-width:66px}.switch[aria-pressed=true]{color:#a9d0ae;border-color:#6d9273;background:#27362b}.result{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5;margin:14px 0 0;color:#c9c2b2}.working{border-left:3px solid #c2a66d;padding-left:12px}.empty{padding:14px 0;color:#a5a8a5}.badge{font-size:11px;border:1px solid #454940;border-radius:20px;padding:5px 9px;color:#c2a66d}.columns{display:grid;grid-template-columns:1fr 1fr;gap:14px}.columns .panel{margin:0}footer{text-align:center;margin:24px 0;color:#8b908a;font-size:11px}@media(max-width:600px){.metrics{grid-template-columns:1fr 1fr}.columns{grid-template-columns:1fr}.actions{gap:7px}main{padding:22px 14px}.panel{padding:17px}}

/* Touch-first phone shell and map surface */
main{max-width:1000px;padding-bottom:calc(52px + env(safe-area-inset-bottom,0px))}
header{margin-bottom:14px}header h1{letter-spacing:-.04em}
nav.tabs{display:grid;grid-template-columns:1fr 1fr;position:sticky;top:0;z-index:10;background:#121416e8;backdrop-filter:blur(14px);gap:8px;padding:9px 0 12px}
.tabs button{border:1px solid #444944;border-radius:10px;font-weight:600;min-height:48px}
.tabs button[aria-selected=true]{color:#f4ddb1;border-color:#b3965d;background:#302c23}
.view[hidden]{display:none!important}
.mapHeading{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}
.mapHeading h2{font:26px Georgia;margin:5px 0 0}
.mapWindow{border:1px solid #494d48;background:radial-gradient(circle at center,#263b35,#111819);border-radius:12px;position:relative;overflow:hidden;min-height:56vh}
.mapWindow iframe{display:block;background:#111819;border:0;width:100%;height:min(70vh,850px);min-height:420px}
.mapStart{display:grid;place-content:center;justify-items:center;text-align:center;gap:13px;padding:35px 20px;min-height:56vh}
.mapStart strong{font:27px Georgia;color:#eadbc4}.mapStart p{max-width:35ch;margin:0;color:#afbbb3;line-height:1.55}
.mapStart button{min-width:165px}
.mapControls{display:flex;gap:10px;flex-wrap:wrap;margin-top:13px}.mapControls a{color:#e6c589;display:inline-flex;align-items:center;justify-content:center;min-height:44px;min-width:170px;border:1px solid #75694f;border-radius:8px;padding:10px;text-decoration:none}
.mapNote{font-size:12px;color:#9daaa4;line-height:1.7;margin:12px 0}
.playerRow{display:block;padding:12px 0;border-bottom:1px solid #333735}
.playerRow:last-child{border:0}.playerTop{display:flex;justify-content:space-between;gap:10px;align-items:center}.playerBadge{font-size:11px;padding:4px 8px;border-radius:30px;border:1px solid #667b68;color:#b5d5bb}.playerBad{color:#f5ac8f;border-color:#855b50}
.playerDetails{display:flex;flex-wrap:wrap;gap:7px;margin-top:8px}.playerDetails span{background:#262d2c;border-radius:5px;color:#c9d3cd;font-size:12px;padding:5px 7px}
.activityText{font-size:13px;color:#c6cfc7;line-height:1.4}
@media(max-width:600px){.mapWindow{margin:0 -5px}.mapWindow iframe{height:calc(100dvh - 225px);min-height:420px;max-height:850px}.mapStart{min-height:55vh}.mapControls a{flex:1}header h1{font-size:28px}main{padding-top:18px}}
</style></head><body><main><header><div><div class=""eyebrow"">ShroudForge Launcher / Enshrouded</div><h1 id=""name"">Your realm</h1><small>Private network · Server controls</small></div><span class=""sigil"" aria-hidden=""true"">◆</span></header>
<nav class=""tabs"" role=""tablist"" aria-label=""Phone companion sections""><button id=""overviewTab"" role=""tab"" aria-selected=""true"" aria-controls=""dashboardView"" onclick=""showTab('overview')"">Overview</button><button id=""mapTab"" role=""tab"" aria-selected=""false"" aria-controls=""mapView"" onclick=""showTab('map')"">3D Map</button></nav>
<div id=""dashboardView"" class=""view"" role=""tabpanel"" aria-labelledby=""overviewTab"">
<section class=""panel hero""><span class=""eyebrow"">Realm status</span><div id=""state"" class=""state""><span class=""dot""></span><span id=""stateText"">Connecting…</span></div><small id=""updated"">Waiting for the host</small><div class=""metrics""><div class=""metric""><small>UPTIME</small><strong id=""uptime"">—</strong></div><div class=""metric""><small>PLAYERS</small><strong id=""count"">—</strong></div><div class=""metric""><small>CPU</small><strong id=""cpu"">—</strong></div><div class=""metric""><small>MEMORY</small><strong id=""memory"">—</strong></div></div><div class=""actions""><button id=""start"" class=""primary"" disabled onclick=""run('Start')"">Start</button><button id=""restart"" disabled onclick=""run('Restart')"">Restart</button><button id=""stop"" class=""danger"" disabled onclick=""run('Stop')"">Stop</button></div><p id=""result"" class=""result"" role=""status"" aria-live=""polite""></p><p class=""muted"">Restart only restarts the server. It never wipes the world. Stop and Restart disconnect players.</p></section>
<div class=""columns""><section class=""panel""><h2>Players online <span id=""playerBadge"" class=""badge"">0</span></h2><div id=""roster"" class=""empty"">Waiting for player information</div><small>Session times are observed by the launcher.</small></section><section class=""panel""><h2>World protection</h2><div class=""eyebrow"">Last verified backup</div><p id=""lastBackup"">Checking…</p><button id=""backup"" class=""primary"" disabled onclick=""run('Backup')"">Back up now</button><p id=""backupResult"" class=""result"" role=""status""></p><p class=""muted"">Copies and verifies your saves. Existing backups are kept. Live copies may span game save cycles.</p></section></div>
<section class=""panel""><h2>World information</h2><div class=""row""><span>Save files</span><strong id=""worldFiles"">Checking</strong></div><div class=""row""><span>Save folder size</span><strong id=""worldSize"">—</strong></div><div class=""row""><span>Last file write</span><strong id=""worldSaved"">—</strong></div><div class=""row""><span>Bases observed</span><strong id=""bases"">—</strong></div></section><section class=""panel""><h2>Known player records</h2><div id=""knownPlayers"" class=""empty""></div><p class=""muted"">Names come from server logs and session history. These records do not prove a separate player-save file exists. The host cannot list character saves stored on other players’ PCs.</p></section><section class=""panel""><h2>Recent server activity</h2><div id=""activity"" class=""empty"">Waiting for recorded events</div><p class=""muted"">Events are from the launcher and server logs; exact location is not available.</p></section>
<section class=""panel""><h2>Automation</h2><div class=""row""><div><strong>Automatic backups</strong><small id=""backupSchedule"">While this launcher is open</small></div><button id=""autoBackup"" class=""switch"" aria-pressed=""false"" disabled onclick=""run(current.autoBackup?'AutoBackupOff':'AutoBackupOn')"">Off</button></div><div class=""row""><div><strong>Crash recovery</strong><small>One restart attempt after 60 seconds. Manual Stop turns this off.</small></div><button id=""recovery"" class=""switch"" aria-pressed=""false"" disabled onclick=""run(current.recovery?'RecoveryOff':'RecoveryOn')"">Off</button></div></section><footer>Keep the host launcher open · Keep this link private</footer></div>
<div id=""mapView"" class=""view"" role=""tabpanel"" aria-labelledby=""mapTab"" hidden>
<section class=""panel""><div class=""mapHeading""><div><div class=""eyebrow"">ShroudForge / Cartography</div><h2>Embervale in 3D</h2></div><span class=""badge"">1.0 terrain</span></div>
<p class=""mapNote"">Real community map data, not a simulated landscape. Use the map's own 3D view and filters for roads, landmarks, chests, quests and resources. Pinch to zoom; drag to explore.</p>
<div class=""mapWindow""><div id=""mapStart"" class=""mapStart""><span class=""sigil"" aria-hidden=""true"">◇</span><strong>Explore Embervale</strong><p>Load the interactive 3D world map only when you need it. A connection to the map provider is required.</p><button class=""primary"" onclick=""loadMap()"">Load interactive map</button></div><iframe id=""gameMap"" title=""External interactive Embervale 3D map by GameVault"" referrerpolicy=""no-referrer"" sandbox=""allow-scripts allow-same-origin allow-forms allow-popups"" allow=""fullscreen"" allowfullscreen hidden></iframe></div>
<div class=""mapControls""><button id=""reloadMap"" onclick=""loadMap(true)"">Reload map</button><a href=""https://enshrouded.gamevault.in/map"" target=""_blank"" rel=""noopener noreferrer"" referrerpolicy=""no-referrer"">Open full map ↗</a></div>
<p class=""mapNote"" id=""mapHelp"" role=""status"">The external viewer may not permit embedding. If the embedded frame remains blank, choose Open full map. No private server key, save, or player data is sent to the map provider. Live player positions are not available through the current server data.</p>
<p class=""mapNote"">3D terrain and map markers provided by GameVault's Companion for Enshrouded. Not affiliated with Keen Games. Map loading is independent of your server controls.</p>
</section></div>
</main><script>
let current={},sending=false,notice='',mapLoaded=false;const el=id=>document.getElementById(id);
function showTab(which){
 const map=which==='map';el('dashboardView').hidden=map;el('mapView').hidden=!map;
 el('overviewTab').setAttribute('aria-selected',String(!map));
 el('mapTab').setAttribute('aria-selected',String(map));
 if(location.hash!==(map?'#map':'#overview'))history.replaceState(null,'',map?'#map':'#overview');
}
function loadMap(reload){
 const frame=el('gameMap');el('mapStart').hidden=true;frame.hidden=false;
 if(!mapLoaded||reload){mapLoaded=true;frame.src='https://enshrouded.gamevault.in/map';text('mapHelp','Loading the community map. Choose its 3D view inside the map. If the embedded frame stays blank, use Open full map instead. The third-party site controls whether embedding is permitted.');}
}
function text(id,value){el(id).textContent=value;}function lock(){document.querySelectorAll('button').forEach(b=>b.disabled=true);}
async function refresh(){try{let r=await fetch('status',{cache:'no-store'});if(!r.ok)throw Error();let s=await r.json();current=s;text('name',s.name);text('stateText',s.busy?'Operation in progress':s.online?'The realm is online':'The realm is resting');el('state').className='state'+(s.online?' online':'');text('updated','Updated '+s.updated);text('uptime',s.uptime);text('count',s.players);text('cpu',s.cpu==='—'?'—':s.cpu+'%');text('memory',s.memory);text('playerBadge',s.players);const list=el('roster');list.replaceChildren();(s.roster||[]).forEach(p=>{
 let row=document.createElement('div');row.className='playerRow';let top=document.createElement('div');top.className='playerTop';
 let name=document.createElement('strong');name.textContent=p.name;let health=document.createElement('span');health.className='playerBadge'+(p.health<55?' playerBad':'');health.textContent=Number.isFinite(p.health)?p.health+' / 100':'Health unknown';top.append(name,health);
 let session=document.createElement('small');session.textContent=p.session;
 let details=document.createElement('div');details.className='playerDetails';[p.connection||'Status unknown','Ping '+(p.ping||'—'),'Jitter '+(p.jitter||'—'),'Dropped '+(p.droppedPackets??'—')].forEach(v=>{let cell=document.createElement('span');cell.textContent=v;details.append(cell);});
 row.append(top,session,details);if(p.lastIssue){let issue=document.createElement('small');issue.textContent='Last issue: '+p.lastIssue;row.append(issue);}list.append(row);
});if(!list.children.length)list.textContent=s.online?'No named players currently observed.':'Server offline';['worldFiles','worldSize','worldSaved','bases'].forEach(id=>text(id,s[id]||'Not observed'));const known=el('knownPlayers');known.replaceChildren();(s.knownPlayers||[]).forEach(p=>{let row=document.createElement('div');row.className='row';let name=document.createElement('strong');name.textContent=p.name;let evidence=document.createElement('small');evidence.textContent=p.evidence;row.append(name,evidence);known.append(row);});if(!known.children.length)known.textContent='No identifiable player records in the available history.';const events=el('activity');events.replaceChildren();(s.activity||[]).forEach(e=>{let row=document.createElement('div');row.className='row';let message=document.createElement('span');message.className='activityText';message.textContent=e.message;let when=document.createElement('small');when.textContent=e.time;row.append(message,when);events.append(row);});if(!events.children.length)events.textContent='No recent activity available.';
text('lastBackup',(s.backupCount>=0?s.backupCount+' verified · ':'')+s.lastBackup);text('backupSchedule','Every '+s.backupMinutes+' minutes'+(s.autoBackup?' · Next '+s.nextBackup:' · Currently off'));text('backupResult',s.backupStatus||'');text('result',s.operation||notice||'Ready for your next action');el('result').className='result'+(s.busy?' working':'');['autoBackup','recovery'].forEach(id=>{el(id).setAttribute('aria-pressed',s[id]?'true':'false');text(id,s[id]?'On':'Off');});const busy=s.busy||!s.controls||sending;el('start').disabled=busy||s.online;el('stop').disabled=el('restart').disabled=busy||!s.online;['backup','autoBackup','recovery'].forEach(id=>el(id).disabled=busy);}catch(e){lock();text('stateText','Connection lost');text('updated','Check the host launcher and Wi-Fi.');}}
async function run(op){if(sending)return;if(['Start','Stop','Restart'].includes(op)&&!confirm(op+' the server?'+(op==='Start'?'':' Connected players will be disconnected.')))return;sending=true;lock();notice='Sending request…';text('result',notice);try{let r=await fetch('command/'+op,{method:'POST',headers:{'X-XHL-Key':location.pathname.split('/')[1]}});let v=await r.json();notice=v.message;text('result',notice);}catch(e){notice='Request result unknown. Check status before retrying.';text('result',notice);}finally{sending=false;}await refresh();}showTab(location.hash==='#map'?'map':'overview');refresh();setInterval(refresh,2000);
</script></body></html>";
 }
}
